CREATE OR REPLACE FUNCTION esim_private.reserve_order(p_order_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o public.esim_orders; r esim_private.order_runs; h uuid; w public.wallets;
BEGIN
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 IF auth.uid() IS DISTINCT FROM o.user_id AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501'; END IF;
 PERFORM esim_private.require_live_owner(o.user_id);
 SELECT * INTO STRICT w FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 IF w.currency IS DISTINCT FROM 'USD' THEN RAISE EXCEPTION 'Unsupported wallet currency'; END IF;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF r.hold_id IS NOT NULL THEN RETURN r.hold_id; END IF;
 IF r.state<>'prepared' OR r.submitted_at IS NOT NULL OR o.provider<>'esimaccess' THEN RAISE EXCEPTION 'Reservation intent unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM public.wallet_transactions WHERE reference_id='esim_'||o.id::text AND type='esim_purchase_debit') THEN
  RAISE EXCEPTION 'Already-debited legacy order cannot be reserved'; END IF;
 UPDATE esim_private.order_runs SET finance_kind='reserved',payer_id=o.user_id WHERE order_id=o.id;
 h:=public.reserve_wallet_funds(o.user_id,o.total_amount_usd,
  CASE WHEN o.operation_kind IN('fixed_recharge','daily_extension') THEN 'esim_recharge' ELSE 'esim_purchase' END,'esim_op:'||o.id::text,'eSIM operation reservation',120);
 UPDATE esim_private.order_runs SET hold_id=h WHERE order_id=o.id;
 UPDATE public.wallet_holds SET expires_at=NULL WHERE id=h;
 RETURN h;
END $function$

CREATE OR REPLACE FUNCTION esim_private.settle_order(p_order_id uuid, p_capture boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r esim_private.order_runs; o public.esim_orders; h public.wallet_holds; tx uuid; charged public.wallet_transactions;
 refunded numeric; ref text;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF r.settlement_state IN('captured','refunded','released') THEN
  IF (p_capture AND r.settlement_state<>'captured') OR (NOT p_capture AND r.settlement_state='captured') THEN RAISE EXCEPTION 'Settlement direction conflict'; END IF;
  RETURN r.settlement_tx_id;
 END IF;
 IF r.receipt IS NULL THEN RAISE EXCEPTION 'Receipt required'; END IF;
 IF r.finance_kind='reserved' THEN
  SELECT * INTO STRICT h FROM public.wallet_holds WHERE id=r.hold_id FOR UPDATE;
  IF h.user_id IS DISTINCT FROM r.payer_id OR h.amount IS DISTINCT FROM o.total_amount_usd OR h.status<>'active'
   OR h.order_reference_id IS DISTINCT FROM 'esim_op:'||o.id::text THEN RAISE EXCEPTION 'Reservation changed'; END IF;
  IF p_capture THEN
   IF r.receipt->>'outcome'<>'success' THEN RAISE EXCEPTION 'Confirmed service required'; END IF;
   UPDATE esim_private.order_runs SET settlement_state='capturing' WHERE order_id=o.id;
   tx:=public.capture_wallet_hold(h.id,CASE WHEN o.operation_kind IN('fixed_recharge','daily_extension') THEN 'esim_recharge_debit' ELSE 'esim_purchase_debit' END,
    'eSIM operation completed',jsonb_build_object('esim_order_id',o.id,'quote_id',o.recharge_quote_id,'action',o.operation_kind));
   UPDATE esim_private.order_runs SET settlement_state='captured',settlement_tx_id=tx WHERE order_id=o.id;
  ELSE
   IF r.state<>'failed' OR r.receipt->>'outcome'<>'failed' THEN RAISE EXCEPTION 'Definitive failure required'; END IF;
   UPDATE esim_private.order_runs SET settlement_state='releasing' WHERE order_id=o.id;
   PERFORM public.release_wallet_hold(h.id,'Verified eSIM failure or no submission');
   UPDATE esim_private.order_runs SET settlement_state='released' WHERE order_id=o.id;
  END IF;
 ELSIF r.finance_kind='legacy_debit' THEN
  SELECT * INTO STRICT charged FROM public.wallet_transactions WHERE id=r.debit_tx_id AND type='esim_purchase_debit'
   AND status='completed' AND reference_id='esim_'||o.id::text AND user_id=r.payer_id FOR UPDATE;
  IF charged.amount<=0 OR charged.amount::text IN('NaN','Infinity','-Infinity') OR charged.amount IS DISTINCT FROM (charged.balance_before-charged.balance_after) THEN RAISE EXCEPTION 'Unproven legacy charge'; END IF;
  IF charged.wallet_id IS DISTINCT FROM (SELECT id FROM public.wallets WHERE user_id=r.payer_id) THEN RAISE EXCEPTION 'Original wallet changed'; END IF;
  ref:='esim_refund_'||o.id::text;
  IF EXISTS(SELECT 1 FROM public.wallet_transactions WHERE status='completed'
   AND (reference_id=ref OR (metadata->>'esim_order_id'=o.id::text AND type IN('refund','esim_purchase_refund')))
   AND (user_id IS DISTINCT FROM r.payer_id OR wallet_id IS DISTINCT FROM charged.wallet_id OR type NOT IN('refund','esim_purchase_refund')
    OR amount<=0 OR balance_after-balance_before IS DISTINCT FROM amount)) THEN RAISE EXCEPTION 'Unproven prior refund'; END IF;
  SELECT coalesce(sum(amount),0) INTO refunded FROM public.wallet_transactions WHERE status='completed' AND
   (reference_id=ref OR (metadata->>'esim_order_id'=o.id::text AND type IN('refund','esim_purchase_refund')));
  IF p_capture THEN
   IF refunded<>0 THEN RAISE EXCEPTION 'Legacy delivery has prior refund; support required'; END IF;
   tx:=charged.id;
   UPDATE esim_private.order_runs SET settlement_state='captured',settlement_tx_id=tx WHERE order_id=o.id;
  ELSE
   IF r.state<>'failed' OR r.receipt->>'outcome'<>'failed' OR refunded>charged.amount THEN RAISE EXCEPTION 'Unproven legacy refund'; END IF;
   IF EXISTS(SELECT 1 FROM public.user_esims WHERE order_id=o.id) THEN RAISE EXCEPTION 'Partial issuance requires support'; END IF;
   IF refunded<charged.amount THEN
    UPDATE esim_private.order_runs SET settlement_state='refunding' WHERE order_id=o.id;
    tx:=public.credit_wallet_for_refund(r.payer_id,charged.amount-refunded,ref,'Verified legacy eSIM failure',NULL,'esim_purchase_refund');
   END IF;
   UPDATE esim_private.order_runs SET settlement_state='refunded',settlement_tx_id=coalesce(tx,settlement_tx_id) WHERE order_id=o.id;
  END IF;
 ELSE RAISE EXCEPTION 'Legacy financial proof required';
 END IF;
 RETURN tx;
END $function$

CREATE OR REPLACE FUNCTION public.accept_esim_daily_purchase(p_quote_id uuid, p_acceptance_key uuid, p_request_key uuid, p_device_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); q esim_private.daily_purchase_quotes; c public.esim_offers_cache; a esim_private.accounts; o public.esim_orders; guard jsonb;
BEGIN
 PERFORM esim_private.require_money_session(u);
 SELECT * INTO q FROM esim_private.daily_purchase_quotes WHERE id=p_quote_id AND owner_id=u AND acceptance_key=p_acceptance_key;
 IF NOT FOUND OR p_request_key IS NULL THEN RETURN '{"status":"QUOTE_UNAVAILABLE"}'::jsonb; END IF;
 PERFORM 1 FROM public.wallets WHERE user_id=u FOR UPDATE;
 SELECT * INTO o FROM public.esim_orders WHERE user_id=u AND (daily_purchase_quote_id=q.id OR client_request_key=p_request_key);
 IF FOUND THEN
  IF o.daily_purchase_quote_id IS DISTINCT FROM q.id THEN RETURN '{"status":"INTENT_CONFLICT"}'::jsonb; END IF;
  RETURN jsonb_build_object('status','ADOPTED','order_id',o.id);
 END IF;
 SELECT * INTO STRICT a FROM esim_private.accounts WHERE id=q.account_id;
 IF NOT a.new_sales_enabled OR NOT a.wallet_boundary_verified OR NOT a.daily_duration_enabled OR NOT a.daily_contract_verified THEN RETURN '{"status":"SALES_DISABLED"}'::jsonb; END IF;
 SELECT * INTO c FROM public.esim_offers_cache WHERE provider='esimaccess' AND bundle_name=q.package_id AND is_active;
 IF q.expires_at<=now() OR c.bundle_name IS NULL OR NOT esim_private.daily_price_current(q.price_id,esim_private.daily_base_context(c),c.catalogue_details)
  OR public.resolve_esim_offer_price(q.wholesale_total,u) IS DISTINCT FROM q.retail_unit
  OR NOT EXISTS(SELECT 1 FROM public.esim_suppliers WHERE code='esimaccess' AND is_active) THEN RETURN '{"status":"STALE_QUOTE"}'::jsonb; END IF;
 IF (esim_private.topup_balance(u,q.retail_total)->>'balance_state')<>'sufficient' THEN RETURN '{"status":"BALANCE_UNAVAILABLE"}'::jsonb; END IF;
 guard:=public.guard_money_action('esim_purchase',q.retail_total,p_device_id,NULL,u);
 IF coalesce((guard->>'blocked')::boolean,true) THEN RETURN '{"status":"DEVICE_BLOCKED"}'::jsonb; END IF;
 INSERT INTO public.esim_orders(user_id,offer_id,bundle_name,provider,quantity,wholesale_price_usd,retail_price_usd,markup_percent,total_amount_usd,status,client_request_key,daily_purchase_quote_id,catalogue_snapshot)
 VALUES(u,q.package_id,q.package_id,'esimaccess',q.quantity,q.wholesale_total,q.retail_unit,round((q.retail_unit/q.wholesale_total-1)*100,2),q.retail_total,'pending',p_request_key,q.id,q.snapshot) RETURNING * INTO o;
 PERFORM esim_private.reserve_order(o.id);
 RETURN jsonb_build_object('status','ACCEPTED','order_id',o.id);
END $function$

CREATE OR REPLACE FUNCTION public.capture_wallet_hold(p_hold_id uuid, p_txn_type text DEFAULT 'topup_debit'::text, p_description text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hold RECORD;
  v_wallet RECORD;
  v_balance_after NUMERIC;
  v_txn_id UUID;
  v_alloc RECORD;
BEGIN
  -- Use the common wallet-before-hold order.
  PERFORM 1 FROM public.wallets WHERE id=(SELECT wallet_id FROM public.wallet_holds WHERE id=p_hold_id) FOR UPDATE;
  -- Lock hold
  SELECT * INTO v_hold
  FROM public.wallet_holds
  WHERE id = p_hold_id
  FOR UPDATE;

  IF v_hold.id IS NULL THEN
    RAISE EXCEPTION 'Hold not found: %', p_hold_id;
  END IF;

  IF v_hold.status = 'captured' THEN
    -- Idempotent retry: return existing transaction if recorded in metadata
    SELECT id INTO v_txn_id
    FROM public.wallet_transactions
    WHERE reference_id = 'hold_' || p_hold_id::text;
    IF v_txn_id IS NOT NULL THEN
      RETURN v_txn_id;
    END IF;
  END IF;

  IF v_hold.status != 'active' THEN
    RAISE EXCEPTION 'Cannot capture hold in status: %', v_hold.status;
  END IF;

  -- Lock wallet
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE id = v_hold.wallet_id
  FOR UPDATE;

  IF v_wallet.balance < v_hold.amount THEN
    RAISE EXCEPTION 'Invariant violation: wallet balance % is less than hold amount %', v_wallet.balance, v_hold.amount;
  END IF;

  v_balance_after := v_wallet.balance - v_hold.amount;

  INSERT INTO esim_private.capture_context(txid,hold_id,wallet_id)
  SELECT txid_current(),p_hold_id,v_wallet.id WHERE EXISTS(SELECT 1 FROM public.wallet_holds h JOIN esim_private.order_runs r ON r.hold_id=h.id WHERE h.wallet_id=v_wallet.id AND h.status='active')
  ON CONFLICT DO NOTHING;
  -- Update wallet balance
  UPDATE public.wallets
  SET balance = v_balance_after,
      total_spent = total_spent + v_hold.amount,
      updated_at = now()
  WHERE id = v_wallet.id;

  -- Update allocated lots (consume remaining_amount)
  FOR v_alloc IN
    SELECT * FROM public.wallet_hold_allocations
    WHERE hold_id = p_hold_id
  LOOP
    UPDATE public.wallet_funding_lots
    SET remaining_amount = remaining_amount - v_alloc.amount,
        status = CASE WHEN remaining_amount - v_alloc.amount = 0 THEN 'fully_consumed' ELSE status END,
        updated_at = now()
    WHERE id = v_alloc.lot_id;
  END LOOP;

  -- Mark hold captured
  UPDATE public.wallet_holds
  SET status = 'captured',
      captured_at = now(),
      updated_at = now()
  WHERE id = p_hold_id;

  -- Record ledger transaction
  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status, metadata, created_at
  ) VALUES (
    v_wallet.id, v_hold.user_id, p_txn_type, v_hold.amount, v_wallet.balance, v_balance_after,
    COALESCE(p_description, 'Purchase completed'),
    'hold_' || p_hold_id::text,
    'completed',
    jsonb_build_object('hold_id', p_hold_id, 'order_type', v_hold.order_type, 'order_reference_id', v_hold.order_reference_id) || COALESCE(p_metadata, '{}'::jsonb),
    now()
  ) RETURNING id INTO v_txn_id;

  DELETE FROM esim_private.capture_context WHERE txid=txid_current() AND hold_id=p_hold_id;
  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.credit_wallet(p_user_id uuid, p_amount numeric, p_type text DEFAULT 'deposit'::text, p_description text DEFAULT 'Wallet deposit'::text, p_reference_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet_id UUID;
  v_balance_before NUMERIC;
  v_balance_after NUMERIC;
  v_txn_id UUID;
BEGIN
  SELECT id, balance INTO v_wallet_id, v_balance_before
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id;
  END IF;

  v_balance_after := v_balance_before + p_amount;

  UPDATE public.wallets
  SET balance = v_balance_after,
      total_deposited = total_deposited + p_amount
  WHERE id = v_wallet_id;

  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status
  ) VALUES (
    v_wallet_id, p_user_id, p_type, p_amount, v_balance_before, v_balance_after,
    p_description, p_reference_id, 'completed'
  ) RETURNING id INTO v_txn_id;

  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_wallet_summary(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet RECORD;
  v_held_amount NUMERIC := 0.00;
  v_available_amount NUMERIC := 0.00;
  v_refundable_amount NUMERIC := 0.00;
  v_promotional_amount NUMERIC := 0.00;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'User ID cannot be null';
  END IF;

  -- Caller must be self or service role / admin
  IF auth.uid() IS NOT NULL AND auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Access denied: cannot view another user wallet summary' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id;

  IF v_wallet.id IS NULL THEN
    -- Return default zero summary
    RETURN jsonb_build_object(
      'wallet_id', null,
      'posted_balance', 0.00,
      'held_amount', 0.00,
      'available_balance', 0.00,
      'refundable_balance', 0.00,
      'promotional_balance', 0.00,
      'currency', 'USD'
    );
  END IF;

  -- Calculate active holds
  SELECT COALESCE(SUM(amount), 0.00) INTO v_held_amount
  FROM public.wallet_holds
  WHERE user_id = p_user_id AND status = 'active';

  v_available_amount := GREATEST(0.00, v_wallet.balance - v_held_amount);

  -- Calculate refundable balance (active paid deposits within deadline)
  SELECT COALESCE(SUM(remaining_amount), 0.00) INTO v_refundable_amount
  FROM public.wallet_funding_lots
  WHERE user_id = p_user_id 
    AND status = 'active'
    AND is_refundable = true
    AND (refund_deadline IS NULL OR refund_deadline > now());

  -- Ensure refundable does not exceed available balance
  v_refundable_amount := LEAST(v_refundable_amount, v_available_amount);

  -- Calculate promotional / gift balance
  SELECT COALESCE(SUM(remaining_amount), 0.00) INTO v_promotional_amount
  FROM public.wallet_funding_lots
  WHERE user_id = p_user_id
    AND status = 'active'
    AND origin_type IN ('promotional', 'unverified_legacy', 'gift_received');

  RETURN jsonb_build_object(
    'wallet_id', v_wallet.id,
    'posted_balance', v_wallet.balance,
    'held_amount', v_held_amount,
    'available_balance', v_available_amount,
    'refundable_balance', v_refundable_amount,
    'promotional_balance', v_promotional_amount,
    'currency', v_wallet.currency
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.quote_esim_daily_purchase(p_offer_id text, p_period_count integer, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); a esim_private.accounts; c public.esim_offers_cache; r esim_private.daily_prices; q esim_private.daily_purchase_quotes; unit_price numeric; retail jsonb;
BEGIN
 PERFORM esim_private.require_live_owner(u);
 IF p_period_count IS NULL OR p_period_count NOT BETWEEN 1 AND 365 OR p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 3 THEN RETURN '{"status":"INVALID_DURATION"}'::jsonb; END IF;
 SELECT * INTO STRICT a FROM esim_private.accounts WHERE provider='esimaccess' AND account_key='primary';
 IF NOT(SELECT discovery_enabled FROM esim_private.recharge_policy WHERE singleton) THEN RETURN '{"status":"DISCOVERY_DISABLED"}'::jsonb; END IF;
 SELECT c0.* INTO c FROM public.esim_offers_cache c0 JOIN public.esim_suppliers s ON s.code=c0.provider AND s.is_active
 WHERE c0.provider='esimaccess' AND c0.is_active AND (c0.bundle_name=p_offer_id OR c0.provider||'_'||c0.bundle_name=p_offer_id);
 IF c.bundle_name IS NULL THEN RETURN '{"status":"INCOMPATIBLE_OFFER"}'::jsonb; END IF;
 IF coalesce(c.catalogue_details->>'plan_type','') NOT IN('daily_throttled','daily_cutoff','daily_unlimited') OR coalesce(c.catalogue_details->>'duration_unit','')<>'DAY' THEN RETURN '{"status":"UNSUPPORTED_DURATION"}'::jsonb; END IF;
 SELECT * INTO r FROM esim_private.daily_prices WHERE account_id=a.id AND package_id=c.bundle_name AND profile_id IS NULL AND period_count=p_period_count ORDER BY revision DESC LIMIT 1;
 IF NOT FOUND OR NOT esim_private.daily_price_current(r.id,esim_private.daily_base_context(c),c.catalogue_details) THEN RETURN '{"status":"DURATION_PRICE_UNAVAILABLE"}'::jsonb; END IF;
 unit_price:=public.resolve_esim_offer_price(r.wholesale_total,u);
 IF unit_price IS NULL OR unit_price<=0 OR unit_price::text IN('NaN','Infinity','-Infinity') THEN RETURN '{"status":"PRICE_UNAVAILABLE"}'::jsonb; END IF;
 retail:=jsonb_build_object('package_id',c.bundle_name,'title',c.description,'currency','USD','retail_total',unit_price*p_quantity,
 'allowance_bytes',c.catalogue_details->>'allowance_bytes','data_type',CASE c.catalogue_details->>'plan_type' WHEN 'daily_throttled' THEN 2 WHEN 'daily_cutoff' THEN 3 ELSE 4 END,
 'duration_value',p_period_count,'duration_unit','DAY','period_count',p_period_count,'effect','new_daily_profile','quote_supported',true,'daily_reset_time',NULL);
 IF(SELECT count(*) FROM esim_private.daily_purchase_quotes WHERE owner_id=u AND created_at>now()-interval '1 minute')>=20 THEN RETURN '{"status":"RATE_LIMITED"}'::jsonb; END IF;
 INSERT INTO esim_private.daily_purchase_quotes(owner_id,account_id,package_id,period_count,quantity,price_id,wholesale_total,retail_unit,retail_total,snapshot,expires_at)
 VALUES(u,a.id,c.bundle_name,p_period_count,p_quantity,r.id,r.wholesale_total,unit_price,unit_price*p_quantity,
 jsonb_build_object('catalogue_details',c.catalogue_details||jsonb_build_object('duration_value',p_period_count,'period_count',p_period_count),
 'daily_source_facts',c.catalogue_details,'daily_price_id',r.id,'daily_context',r.context,'period_count',p_period_count,'duration_days',p_period_count,
 'daily_base_price',c.wholesale_price_usd,'countries',c.countries,'data_amount_mb',c.data_amount_mb,'is_unlimited',c.is_unlimited),least(r.expires_at,now()+interval '2 minutes')) RETURNING * INTO q;
 RETURN jsonb_build_object('status','QUOTED','quote_id',q.id,'acceptance_key',q.acceptance_key,'owner_id',u,'payer_id',u,'action','daily_purchase','offer',retail,'quantity',q.quantity,
 'expires_at',q.expires_at,'acceptance_enabled',a.new_sales_enabled AND a.wallet_boundary_verified AND a.daily_duration_enabled AND a.daily_contract_verified)||esim_private.topup_balance(u,q.retail_total);
END $function$

CREATE OR REPLACE FUNCTION public.request_esim_purchase_v2(p_offer_id text, p_quantity integer, p_device_id text, p_request_key uuid, p_reviewed_total numeric, p_expected_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_offer RECORD;
  v_supplier_markup numeric;
  v_markup_percent numeric := 30.0;
  v_retail_price numeric(10,2);
  v_total_cost numeric(10,2);
  v_wallet_balance numeric(10,2);
  v_order_id uuid;
  v_txn_ref text;
  v_guard jsonb;
  existing public.esim_orders;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'UNAUTHORIZED');
  END IF;

  IF p_expected_user IS DISTINCT FROM v_user_id THEN RETURN jsonb_build_object('success',false,'code','ACCOUNT_CHANGED'); END IF;
  PERFORM esim_private.require_money_session(v_user_id);
  IF p_request_key IS NULL OR p_reviewed_total IS NULL OR p_reviewed_total<=0 OR p_reviewed_total::text IN('NaN','Infinity','-Infinity') THEN
    RETURN jsonb_build_object('success',false,'code','INVALID_REVIEWED_INTENT'); END IF;
  PERFORM 1 FROM public.wallets WHERE user_id=v_user_id FOR UPDATE;
  SELECT * INTO existing FROM public.esim_orders WHERE user_id=v_user_id AND client_request_key=p_request_key;
  IF FOUND THEN
    IF existing.offer_id IS DISTINCT FROM p_offer_id OR existing.quantity IS DISTINCT FROM p_quantity OR existing.total_amount_usd IS DISTINCT FROM p_reviewed_total THEN
      RETURN jsonb_build_object('success',false,'code','INTENT_CONFLICT'); END IF;
    RETURN jsonb_build_object('success',true,'order_id',existing.id,'status',existing.status,'adopted',true);
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = v_user_id AND is_suspended = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Account is suspended. Purchases are disabled.');
  END IF;

  PERFORM public.enforce_rate_limit('esim_purchase', v_user_id::text);

  IF p_quantity IS NULL OR p_quantity < 1 OR p_quantity > 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Quantity must be between 1 and 3');
  END IF;

  SELECT c.* INTO v_offer
  FROM public.esim_offers_cache c
  JOIN public.esim_suppliers s ON s.code = c.provider AND s.is_active = true
  WHERE (c.bundle_name = p_offer_id OR (c.provider || '_' || c.bundle_name = p_offer_id))
    AND c.is_active = true
  ORDER BY c.updated_at DESC
  LIMIT 1;

  IF v_offer IS NULL OR v_offer.bundle_name IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'eSIM offer not found or inactive');
  END IF;

  IF v_offer.catalogue_details->>'plan_type' IN('daily_throttled','daily_cutoff','daily_unlimited') THEN RETURN jsonb_build_object('success',false,'code','DURATION_REQUIRED'); END IF;
  -- Use canonical tier-based pricing via resolve_esim_offer_price
  v_retail_price := public.resolve_esim_offer_price(v_offer.wholesale_price_usd, v_user_id);
  IF v_retail_price IS NULL OR v_retail_price <= 0 THEN
    SELECT markup_percent_override INTO v_supplier_markup
    FROM public.esim_suppliers
    WHERE code = v_offer.provider;

    IF v_supplier_markup IS NOT NULL THEN
      v_markup_percent := v_supplier_markup;
    ELSE
      BEGIN
        SELECT config_value::numeric INTO v_markup_percent
        FROM public.system_configs WHERE config_key = 'ESIM_MARKUP_PERCENT';
      EXCEPTION WHEN OTHERS THEN v_markup_percent := 30.0; END;
    END IF;
    IF v_markup_percent IS NULL THEN v_markup_percent := 30.0; END IF;

    v_retail_price := round(v_offer.wholesale_price_usd * (1.0 + (v_markup_percent / 100.0)), 2);
  ELSE
    v_markup_percent := round(((v_retail_price - v_offer.wholesale_price_usd) / NULLIF(v_offer.wholesale_price_usd, 0)) * 100.0, 2);
  END IF;

  v_total_cost := v_retail_price * p_quantity;
  IF v_total_cost IS DISTINCT FROM p_reviewed_total THEN RETURN jsonb_build_object('success',false,'code','PRICE_CHANGED'); END IF;

  SELECT (public.get_wallet_summary(v_user_id)->>'available_balance')::numeric INTO v_wallet_balance;

  IF v_wallet_balance < v_total_cost THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INSUFFICIENT_FUNDS',
      'error', 'Insufficient wallet balance. Required: $' || v_total_cost::text || ', Available: $' || v_wallet_balance::text
    );
  END IF;

  v_guard := public.guard_money_action('esim_purchase', v_total_cost, p_device_id, NULL, v_user_id);
  IF (v_guard ->> 'blocked')::boolean THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'DEVICE_BLOCKED',
      'reason', v_guard ->> 'reason',
      'error', 'This purchase was stopped by a security check on this device. Contact support if this is a mistake.'
    );
  END IF;

  INSERT INTO public.esim_orders (
    user_id, offer_id, bundle_name, provider, quantity, wholesale_price_usd, retail_price_usd, markup_percent, total_amount_usd, status, client_request_key
  ) VALUES (
    v_user_id, p_offer_id, v_offer.bundle_name, v_offer.provider, p_quantity, v_offer.wholesale_price_usd, v_retail_price, v_markup_percent, v_total_cost, 'pending', p_request_key
  ) RETURNING id INTO v_order_id;

  v_txn_ref := 'esim_' || v_order_id::text;

  PERFORM esim_private.reserve_order(v_order_id);

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'retail_price_usd', v_retail_price,
    'total_amount_usd', v_total_cost,
    'status', 'pending'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_esim_offer_price(p_wholesale_price numeric, p_user_id uuid DEFAULT auth.uid())
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tier TEXT;
  v_fee  NUMERIC;
BEGIN
  IF p_wholesale_price IS NULL OR p_wholesale_price <= 0 THEN
    RETURN 0.00;
  END IF;

  v_tier := public.resolve_account_commerce_benefit(p_user_id);
  v_fee := public.resolve_app_fee('esimofferfee', v_tier, p_wholesale_price);

  IF v_fee IS NULL OR v_fee = 0 THEN
    v_fee := CASE v_tier
      WHEN 'premium'  THEN round(p_wholesale_price * 0.05, 2)
      WHEN 'standard' THEN round(p_wholesale_price * 0.07, 2)
      ELSE round(p_wholesale_price * 0.10, 2)
    END;
  END IF;

  RETURN round(p_wholesale_price + v_fee, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.service_esim_claim_order(p_account_key text DEFAULT 'primary'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a esim_private.accounts%ROWTYPE; r esim_private.order_runs%ROWTYPE; result jsonb;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT a FROM esim_private.accounts WHERE account_key=p_account_key;
 SELECT run.* INTO r FROM esim_private.order_runs run JOIN public.esim_orders o ON o.id=run.order_id
 WHERE run.account_id=a.id AND run.state<>'completed' AND o.user_id IS NOT NULL
   AND o.status IN('pending','processing') AND run.next_check_at<=now()
   AND (run.lease_until IS NULL OR run.lease_until<now())
   AND (run.state<>'prepared' OR run.finance_kind='reserved')
 ORDER BY run.next_check_at FOR UPDATE OF run SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN NULL; END IF;
 UPDATE esim_private.order_runs SET lease=gen_random_uuid(),lease_until=now()+interval '2 minutes',attempts=attempts+1
 WHERE order_id=r.order_id RETURNING * INTO r;
 UPDATE public.esim_orders SET status='processing',delivery_state=r.state,updated_at=now() WHERE id=r.order_id;
 SELECT jsonb_build_object('order_id',o.id,'user_id',o.user_id,'bundle_name',o.bundle_name,'quantity',o.quantity,
  'wholesale_price_usd',o.wholesale_price_usd,'catalogue_snapshot',o.catalogue_snapshot,'lease',r.lease,
  'state',r.state,'submission_ref',r.submission_ref,'provider_order_ref',r.provider_order_ref,'hinted_order_ref',r.hinted_order_ref,'operation_kind',o.operation_kind,'has_receipt',r.receipt IS NOT NULL,
 'supplier_profile_ref',o.catalogue_snapshot->>'supplier_profile_ref','iccid',o.catalogue_snapshot->>'iccid')
 INTO result FROM public.esim_orders o WHERE o.id=r.order_id;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.service_esim_finish_control(p_operation_id uuid, p_lease uuid, p_observation jsonb DEFAULT NULL::jsonb, p_error_code text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE op esim_private.controls;p public.user_esims;confirmed boolean;
BEGIN
 PERFORM esim_private.require_service();SELECT * INTO STRICT op FROM esim_private.controls WHERE id=p_operation_id;
 SELECT * INTO STRICT p FROM public.user_esims WHERE id=op.profile_id FOR UPDATE;
 SELECT * INTO STRICT op FROM esim_private.controls WHERE id=p_operation_id FOR UPDATE;
 IF p_lease IS NULL OR op.lease IS DISTINCT FROM p_lease OR op.lease_until<now() OR op.state NOT IN('prepared','submitted','reconciling') THEN RETURN false; END IF;
 IF p_error_code IS NOT NULL AND p_error_code!~'^[A-Z0-9_]{1,64}$' THEN RAISE EXCEPTION 'Invalid error code'; END IF;
 confirmed:=op.submitted_at IS NOT NULL AND p_observation->>'supplier_profile_ref'=p.supplier_profile_ref AND p_observation->>'iccid'=p.iccid
 AND p_observation->>'provider_order_ref'=(SELECT provider_order_ref FROM esim_private.order_runs WHERE order_id=p.order_id)
 AND (p_observation->>'checked_at')::timestamptz>=op.submitted_at AND (p_observation->>'checked_at')::timestamptz<=clock_timestamp()+interval '5 seconds'
 AND CASE op.action WHEN 'cancel' THEN p_observation->>'profile_state'='cancelled' WHEN 'suspend' THEN p_observation->>'profile_state'='suspended' WHEN 'resume' THEN p_observation->>'profile_state' IN('issued','active') END;
 IF coalesce(confirmed,false) AND (p.last_observation_at IS NULL OR (p_observation->>'checked_at')::timestamptz>=p.last_observation_at) THEN
  UPDATE public.user_esims SET profile_state=p_observation->>'profile_state',provider_state=p_observation->'provider_state',last_observation_at=(p_observation->>'checked_at')::timestamptz,
   bundle_state=CASE WHEN op.action='cancel' THEN 'cancelled' ELSE bundle_state END WHERE id=p.id;
  UPDATE esim_private.controls SET state=CASE WHEN action='cancel' THEN 'refund_pending' ELSE 'completed' END,error_code=NULL,lease=NULL,lease_until=NULL,updated_at=now() WHERE id=op.id;
 ELSE
  -- No resubmission on a timeout or a state that has not propagated yet.
  UPDATE esim_private.controls SET state=CASE WHEN submitted_at IS NULL THEN 'failed' WHEN attempts>=12 THEN 'support_required' ELSE 'reconciling' END,
   error_code=coalesce(p_error_code,'CONTROL_OUTCOME_UNKNOWN'),next_check_at=now()+interval '5 minutes',lease=NULL,lease_until=NULL,updated_at=now() WHERE id=op.id;
 END IF;
 RETURN coalesce(confirmed,false);
END $function$

CREATE OR REPLACE FUNCTION public.service_esim_mark_submitted(p_order_id uuid, p_lease uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r esim_private.order_runs; o public.esim_orders; p public.user_esims; q esim_private.recharge_quotes; reason text; reject_code text; available numeric;
BEGIN
 PERFORM esim_private.require_service();SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id;
 PERFORM 1 FROM public.wallets WHERE user_id=o.user_id FOR UPDATE;
 IF o.recharge_profile_id IS NOT NULL THEN SELECT * INTO STRICT p FROM public.user_esims WHERE id=o.recharge_profile_id FOR UPDATE; END IF;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=o.id FOR UPDATE;
 IF p_lease IS NULL OR r.lease IS DISTINCT FROM p_lease OR r.lease_until IS NULL OR r.lease_until<now() OR r.state<>'prepared' OR r.submitted_at IS NOT NULL THEN RETURN false; END IF;
 IF r.finance_kind<>'reserved' OR r.hold_id IS NULL OR r.payer_id IS DISTINCT FROM o.user_id THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.esim_suppliers WHERE code=o.provider AND is_active) THEN reject_code:='SUPPLIER_DISABLED'; END IF;
 IF o.operation_kind IN('fixed_recharge','daily_extension') THEN
  IF NOT esim_private.recharge_can_accept() THEN reject_code:='SUBMISSION_DISABLED'; END IF;
  SELECT * INTO STRICT q FROM esim_private.recharge_quotes WHERE id=o.recharge_quote_id;
  IF q.expires_at<=now() THEN reject_code:='QUOTE_EXPIRED'; END IF;
  IF q.context IS DISTINCT FROM esim_private.topup_context(p) OR p.user_id IS DISTINCT FROM o.user_id
   OR p.supplier_account_id IS DISTINCT FROM r.account_id OR esim_private.topup_refusal_base(p) IS NOT NULL THEN reject_code:='PROFILE_CHANGED'; END IF;
  IF EXISTS(SELECT 1 FROM public.esim_orders WHERE recharge_profile_id=p.id AND id<>o.id AND status IN('pending','processing')) THEN reject_code:='PROFILE_CHANGED'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM esim_private.accounts WHERE id=r.account_id AND new_sales_enabled AND wallet_boundary_verified) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
  IF o.daily_purchase_quote_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.esim_offers_cache WHERE provider=o.provider AND bundle_name=o.bundle_name AND is_active AND wholesale_price_usd=o.wholesale_price_usd) THEN reject_code:='PRICE_CHANGED'; END IF;
 END IF;
 IF public.resolve_esim_offer_price(o.wholesale_price_usd,o.user_id) IS DISTINCT FROM o.retail_price_usd THEN reject_code:='PRICE_CHANGED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=o.user_id AND NOT coalesce(is_suspended,false)) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.wallet_holds WHERE id=r.hold_id AND status='active' AND user_id=r.payer_id AND amount=o.total_amount_usd AND expires_at IS NULL) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 SELECT w.balance-coalesce((SELECT sum(amount) FROM public.wallet_holds WHERE wallet_id=w.id AND status='active'),0) INTO available FROM public.wallets w WHERE user_id=r.payer_id AND currency='USD';
 IF available IS NULL OR available<0 OR available::text IN('NaN','Infinity','-Infinity') THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 IF (o.daily_purchase_quote_id IS NOT NULL OR o.operation_kind='daily_extension') AND NOT EXISTS(SELECT 1 FROM esim_private.accounts WHERE id=r.account_id AND daily_duration_enabled AND daily_contract_verified) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 IF NOT esim_private.daily_order_current(o) THEN reject_code:='PRICE_CHANGED'; END IF;
 IF o.recharge_profile_id IS NOT NULL AND esim_private.control_pending(o.recharge_profile_id) THEN reject_code:='PROFILE_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM esim_private.automation_orders WHERE order_id=o.id) AND NOT EXISTS(
 SELECT 1 FROM esim_private.automation_orders x JOIN esim_private.automation_consents c ON c.profile_id=x.profile_id JOIN esim_private.accounts a ON a.id=r.account_id
 WHERE x.order_id=o.id AND c.enabled AND c.revision=x.consent_revision AND c.owner_id=o.user_id AND c.payer_id=r.payer_id
 AND (c.ends_at IS NULL OR c.ends_at>now()) AND a.automation_enabled AND o.total_amount_usd<=c.max_charge AND o.total_amount_usd<=c.reviewed_charge
 AND esim_private.automation_exposure(c.profile_id)<=c.monthly_cap) THEN reject_code:='SUBMISSION_DISABLED'; END IF;
 IF reject_code IS NOT NULL THEN PERFORM public.service_esim_fail_before_submit(o.id,p_lease,reject_code);RETURN false; END IF;
 UPDATE esim_private.order_runs SET state='submitted',submitted_at=now(),updated_at=now() WHERE order_id=o.id;
 UPDATE public.esim_orders SET delivery_state='submitted' WHERE id=o.id;RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.service_esim_order_checkpoint(p_order_id uuid, p_lease uuid, p_provider_order_ref text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r esim_private.order_runs%ROWTYPE; state_value text;
BEGIN
 PERFORM esim_private.require_service();
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=p_order_id FOR UPDATE;
 IF p_lease IS NULL OR r.lease IS NULL OR r.lease_until IS NULL OR r.lease IS DISTINCT FROM p_lease OR r.lease_until<now() OR r.state='completed' THEN RETURN false; END IF;
 IF p_error_code IS NOT NULL AND p_error_code!~'^[A-Z0-9_]{1,64}$' THEN RAISE EXCEPTION 'Invalid error code'; END IF;
 IF r.provider_order_ref IS NOT NULL AND p_provider_order_ref IS NOT NULL AND r.provider_order_ref<>p_provider_order_ref THEN RAISE EXCEPTION 'Provider order reference conflict'; END IF;
 state_value:=CASE WHEN coalesce(r.provider_order_ref,p_provider_order_ref) IS NULL THEN 'support_required' ELSE 'reconciling' END;
 UPDATE esim_private.order_runs SET state=state_value,provider_order_ref=coalesce(provider_order_ref,p_provider_order_ref),
  error_code=p_error_code,lease=NULL,lease_until=NULL,updated_at=now(),
  next_check_at=CASE WHEN state_value='support_required' AND hinted_order_ref IS NULL THEN NULL
    WHEN p_error_code IS NULL THEN now()+interval '10 seconds'
    ELSE now()+make_interval(secs=>least(21600,60*power(2,least(attempts,8)))::integer) END WHERE order_id=p_order_id;
 UPDATE public.esim_orders SET delivery_state=state_value,updated_at=now() WHERE id=p_order_id;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.service_esim_save_issuance(p_order_id uuid, p_lease uuid, p_provider_order_ref text, p_profiles jsonb, p_transaction_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r esim_private.order_runs%ROWTYPE; o public.esim_orders%ROWTYPE; item jsonb;
 existing public.user_esims%ROWTYPE; new_id uuid; count_profiles integer; conflict boolean:=false;
BEGIN
 PERFORM esim_private.require_service();
 PERFORM 1 FROM public.wallets WHERE user_id=(SELECT user_id FROM public.esim_orders WHERE id=p_order_id) FOR UPDATE;
 SELECT * INTO STRICT r FROM esim_private.order_runs WHERE order_id=p_order_id FOR UPDATE;
 IF r.state='completed' THEN RETURN jsonb_build_object('completed',true); END IF;
 IF p_lease IS NULL OR r.lease IS NULL OR r.lease_until IS NULL OR r.lease IS DISTINCT FROM p_lease OR r.lease_until<now() THEN RAISE EXCEPTION 'Expired order lease'; END IF;
 SELECT * INTO STRICT o FROM public.esim_orders WHERE id=p_order_id FOR UPDATE;
 IF o.operation_kind<>'purchase' OR o.user_id IS NULL OR o.provider<>'esimaccess' OR o.status NOT IN('pending','processing') THEN RAISE EXCEPTION 'Order is not eligible'; END IF;
 IF nullif(p_provider_order_ref,'') IS NULL OR
  (r.provider_order_ref IS NOT NULL AND r.provider_order_ref<>p_provider_order_ref) OR
  (r.provider_order_ref IS NULL AND p_transaction_id IS DISTINCT FROM r.submission_ref) THEN RAISE EXCEPTION 'Unproven order binding'; END IF;
 IF p_profiles IS NULL OR jsonb_typeof(p_profiles)<>'array' OR jsonb_array_length(p_profiles)>o.quantity OR octet_length(p_profiles::text)>65536 THEN RAISE EXCEPTION 'Invalid allocation batch'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_profiles) LOOP
  IF item->>'provider_order_ref' IS DISTINCT FROM p_provider_order_ref OR item->>'issuance_proven' IS DISTINCT FROM 'true'
   OR coalesce(item->>'supplier_profile_ref','')='' OR coalesce(item->>'iccid','')!~'^[0-9]{15,22}$'
   OR coalesce(item->>'lpa_string','')!~'^LPA:1\$[^$[:space:]]+\$[^$[:space:]]+'
  OR coalesce(item->>'smdp_address','')='' OR coalesce(item->>'matching_id','')=''
  OR split_part(item->>'lpa_string','$',2) IS DISTINCT FROM item->>'smdp_address'
  OR split_part(item->>'lpa_string','$',3) IS DISTINCT FROM item->>'matching_id'
  OR item->>'profile_state' IN('cancelled','revoked','expired') THEN CONTINUE; END IF;
  SELECT * INTO existing FROM public.user_esims WHERE provider='esimaccess' AND supplier_account_id=r.account_id
   AND supplier_profile_ref=item->>'supplier_profile_ref' FOR UPDATE;
  IF FOUND THEN
   IF existing.user_id IS DISTINCT FROM o.user_id OR existing.order_id<>o.id OR existing.iccid<>item->>'iccid'
    OR existing.lpa_string<>item->>'lpa_string' THEN conflict:=true; END IF;
   CONTINUE;
  END IF;
  BEGIN
   INSERT INTO public.user_esims(user_id,order_id,provider,bundle_name,iccid,smdp_address,matching_id,lpa_string,
     status,purchased_at,data_total_mb,data_remaining_mb,supplier_account_id,supplier_profile_ref,profile_state,
     installation_state,bundle_state,provider_state,activation_trigger,confirmed_expires_at,plan_details,
     data_total_bytes,data_used_bytes,data_remaining_bytes,last_usage_check,last_observation_at)
   VALUES(o.user_id,o.id,o.provider,o.bundle_name,item->>'iccid',item->>'smdp_address',item->>'matching_id',item->>'lpa_string',
    'active',o.created_at,coalesce(floor((item->>'data_total_bytes')::numeric/1048576)::bigint,0),
    coalesce(floor((item->>'data_remaining_bytes')::numeric/1048576)::bigint,0),r.account_id,item->>'supplier_profile_ref',coalesce(item->>'profile_state','unknown'),
    coalesce(item->>'installation_state','unknown'),coalesce(item->>'bundle_state','unknown'),coalesce(item->'provider_state','{}'),
    coalesce(item->>'activation_trigger','unknown'),(item->>'confirmed_expires_at')::timestamptz,o.catalogue_snapshot->'catalogue_details',
    (item->>'data_total_bytes')::bigint,(item->>'data_used_bytes')::bigint,(item->>'data_remaining_bytes')::bigint,
    CASE WHEN item->>'data_remaining_bytes' IS NOT NULL THEN now() END,clock_timestamp()) RETURNING id INTO new_id;
   INSERT INTO esim_private.profile_work(profile_id) VALUES(new_id);
  EXCEPTION WHEN unique_violation THEN conflict:=true;
  END;
 END LOOP;
 SELECT count(*) INTO count_profiles FROM public.user_esims WHERE order_id=o.id AND user_id=o.user_id
  AND provider=o.provider AND supplier_account_id=r.account_id AND supplier_profile_ref IS NOT NULL;
 IF count_profiles=o.quantity AND NOT conflict THEN
  UPDATE esim_private.order_runs SET receipt=jsonb_build_object('outcome','success','source','verified_issuance',
   'transaction_id',submission_ref,'provider_order_ref',p_provider_order_ref,'profiles',count_profiles),receipt_at=now() WHERE order_id=o.id;
  PERFORM esim_private.settle_order(o.id,true);
 END IF;
 UPDATE esim_private.order_runs SET provider_order_ref=p_provider_order_ref,state=CASE WHEN conflict THEN 'support_required'
  WHEN count_profiles=o.quantity THEN 'completed' ELSE 'reconciling' END,
  next_check_at=CASE WHEN count_profiles=o.quantity OR conflict THEN NULL ELSE now()+interval '1 minute' END,
  lease=NULL,lease_until=NULL,error_code=CASE WHEN conflict THEN 'IDENTITY_CONFLICT' WHEN count_profiles<o.quantity THEN 'PARTIAL_ISSUANCE' END,updated_at=now()
 WHERE order_id=o.id;
 UPDATE public.esim_orders SET status=CASE WHEN count_profiles=o.quantity AND NOT conflict THEN 'completed' ELSE 'processing' END,
  delivery_state=CASE WHEN conflict THEN 'support_required' WHEN count_profiles=o.quantity THEN 'completed' ELSE 'reconciling' END,
  provider_order_ref=p_provider_order_ref,updated_at=now() WHERE id=o.id;
 RETURN jsonb_build_object('completed',count_profiles=o.quantity AND NOT conflict,'profiles',count_profiles,'conflict',conflict);
END $function$

CREATE OR REPLACE FUNCTION public.service_esim_set_refund_scope(p_profile_id uuid, p_items jsonb, p_source_reference text, p_observed_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.user_esims; i jsonb; d public.wallet_transactions; o public.esim_orders; amount numeric;
BEGIN
 PERFORM esim_private.require_service();SELECT * INTO STRICT p FROM public.user_esims WHERE id=p_profile_id FOR UPDATE;
 IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 20
  OR p_source_reference IS NULL OR length(p_source_reference) NOT BETWEEN 8 AND 200 OR p_observed_at IS NULL OR p_observed_at<now()-interval '10 minutes' OR p_observed_at>clock_timestamp() THEN RAISE EXCEPTION 'Invalid refund evidence'; END IF;
 IF (SELECT count(DISTINCT value->>'debit_id') FROM jsonb_array_elements(p_items))<>jsonb_array_length(p_items) THEN RAISE EXCEPTION 'Duplicate refund binding'; END IF;
 FOR i IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  SELECT * INTO STRICT d FROM public.wallet_transactions WHERE id=(i->>'debit_id')::uuid;
  SELECT ord.* INTO STRICT o FROM public.esim_orders ord JOIN esim_private.order_runs r ON r.order_id=ord.id
   WHERE r.settlement_tx_id=d.id AND r.settlement_state='captured' AND ord.provider='esimaccess'
    AND ((ord.id=p.order_id AND ord.quantity=1) OR ord.recharge_profile_id=p.id);
  amount:=(i->>'amount')::numeric;
  IF d.type NOT IN('esim_purchase_debit','esim_recharge_debit') OR d.status IS DISTINCT FROM 'completed'
   OR d.amount<=0 OR d.amount IS DISTINCT FROM d.balance_before-d.balance_after OR amount IS NULL OR amount<=0
   OR amount::text IN('NaN','Infinity','-Infinity') OR amount<>round(amount,2) OR amount>d.amount OR amount>o.total_amount_usd
   OR d.user_id IS DISTINCT FROM o.user_id OR EXISTS(SELECT 1 FROM esim_private.cancellation_refunds WHERE debit_id=d.id)
   OR EXISTS(SELECT 1 FROM public.wallet_transactions WHERE status='completed' AND (reference_id IN('esim_refund_'||o.id::text,'esim_cancel:'||d.id::text)
     OR (metadata->>'esim_order_id'=o.id::text AND type IN('refund','esim_purchase_refund','esim_recharge_refund')))) THEN RAISE EXCEPTION 'Unproven or previously refunded charge'; END IF;
 END LOOP;
 -- Every evidenced captured base/recharge must be accounted for. Exclusions
 -- and partial policies require support rather than silently omitting a charge.
 IF EXISTS(SELECT 1 FROM public.esim_orders o0 JOIN esim_private.order_runs r ON r.order_id=o0.id
  WHERE (o0.id=p.order_id OR o0.recharge_profile_id=p.id) AND r.settlement_state='captured'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_items) x WHERE (x->>'debit_id')::uuid=r.settlement_tx_id)) THEN RAISE EXCEPTION 'Incomplete refund scope'; END IF;
 INSERT INTO esim_private.refund_scopes(profile_id,context,items,source_reference,observed_at,expires_at)
 VALUES(p.id,esim_private.refund_context(p.id),p_items,p_source_reference,p_observed_at,p_observed_at+interval '10 minutes')
 ON CONFLICT(profile_id) DO UPDATE SET version=gen_random_uuid(),context=excluded.context,items=excluded.items,source_reference=excluded.source_reference,
 observed_at=excluded.observed_at,expires_at=excluded.expires_at WHERE refund_scopes.observed_at<=excluded.observed_at;
 RETURN FOUND;
END $function$

CREATE OR REPLACE FUNCTION public.snapshot_esim_catalogue_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.daily_purchase_quote_id IS NOT NULL THEN
  SELECT snapshot INTO STRICT NEW.catalogue_snapshot FROM esim_private.daily_purchase_quotes WHERE id=NEW.daily_purchase_quote_id AND owner_id=NEW.user_id AND package_id=NEW.bundle_name AND quantity=NEW.quantity AND wholesale_total=NEW.wholesale_price_usd AND retail_total=NEW.total_amount_usd;
  RETURN NEW;
 END IF;
 IF NEW.operation_kind IN('fixed_recharge','daily_extension') THEN RETURN NEW; END IF;
  SELECT jsonb_build_object('provider',c.provider,'bundle_name',c.bundle_name,
    'catalogue_details',c.catalogue_details,'countries',c.countries,
    'data_amount_mb',c.data_amount_mb,'duration_days',c.duration_days,
    'is_unlimited',c.is_unlimited,'retail_price_usd',NEW.retail_price_usd,
    'catalogue_observed_at',c.updated_at)
  INTO NEW.catalogue_snapshot FROM public.esim_offers_cache c
  WHERE c.provider=NEW.provider AND c.bundle_name=NEW.bundle_name;
  RETURN NEW;
END;
$function$
